def transform(grid):
    h,w=len(grid),len(grid[0]); bg=8
    unseen={(r,c) for r in range(h) for c in range(w) if grid[r][c]!=bg}; comps=[]
    while unseen:
        seed=unseen.pop(); comp={seed}; stack=[seed]
        while stack:
            r,c=stack.pop()
            for dr in (-1,0,1):
                for dc in (-1,0,1):
                    p=(r+dr,c+dc)
                    if p in unseen: unseen.remove(p); comp.add(p); stack.append(p)
        comps.append(comp)
    comp=max(comps,key=lambda x:len({grid[r][c] for r,c in x}))
    out=[[bg]*w for _ in range(h)]
    for r,c in comp: out[r][c]=grid[r][c]
    rs=[r for r,c in comp]; cs=[c for r,c in comp]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
